<?php
declare(strict_types=1);
require __DIR__ . '/src/Database.php'; require __DIR__ . '/src/CombinationService.php';
$db = Database::connect();
$base = rtrim(getenv('APP_BASE_PATH') ?: dirname($_SERVER['SCRIPT_NAME'] ?? ''), '/');
function go(string $url): never { header('Location: ' . $url); exit; }
function id(string $key): int { return filter_input(INPUT_POST, $key, FILTER_VALIDATE_INT) ?: 0; }
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $action = $_POST['action'] ?? ''; $systemId = id('system_id');
    if ($action === 'system') { $db->prepare('INSERT INTO systems(name) VALUES(?)')->execute([trim($_POST['name'])]); $systemId = (int)$db->lastInsertId(); }
    if ($action === 'type') $db->prepare('INSERT INTO element_types(system_id,name) VALUES(?,?)')->execute([$systemId, trim($_POST['name'])]);
    if ($action === 'element') { $type = id('element_type_id'); $valid = $db->prepare('SELECT 1 FROM element_types WHERE id=? AND system_id=?'); $valid->execute([$type,$systemId]); if ($valid->fetchColumn()) $db->prepare('INSERT INTO elements(system_id,element_type_id,text_value) VALUES(?,?,?)')->execute([$systemId,$type,trim($_POST['text_value'])]); }
    if ($action === 'structure') { $slots = array_values(array_filter(array_map('intval', $_POST['slots'] ?? []))); $valid = $db->prepare('SELECT COUNT(*) FROM element_types WHERE system_id=? AND id IN (' . implode(',', array_fill(0,count($slots),'?')) . ')'); if ($slots && ($valid->execute([$systemId,...$slots]) || true) && (int)$valid->fetchColumn() === count(array_unique($slots))) $db->prepare('INSERT INTO combination_structures(system_id,name,slots) VALUES(?,?,?)')->execute([$systemId,trim($_POST['name']),json_encode($slots)]); }
    if ($action === 'generate') { $new = (new CombinationService($db))->generate($systemId,id('structure_id')); go("{$base}/?system={$systemId}&created={$new}"); }
    go("{$base}/?system={$systemId}");
}
$systems = $db->query('SELECT * FROM systems ORDER BY name')->fetchAll(); $systemId = filter_input(INPUT_GET,'system',FILTER_VALIDATE_INT) ?: (int)($systems[0]['id'] ?? 0);
$load = static fn(string $table) => $systemId ? (($s=$db->prepare("SELECT * FROM {$table} WHERE system_id=? ORDER BY id DESC")) && $s->execute([$systemId]) ? $s->fetchAll() : []) : [];
$types=$load('element_types'); $elements=$load('elements'); $structures=$load('combination_structures'); $combinations=$load('generated_combinations');
$typeNames=array_column($types,'name','id');
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lexical Chunks</title><link rel="stylesheet" href="<?=htmlspecialchars($base)?>/assets/app.css"></head><body><aside><div class="brand">◈ <span>Lexical<br><b>Chunks</b></span></div><nav><a class="active" href="#visao">Visão geral</a><a href="#estruturas">Estruturas</a><a href="#resultados">Combinações</a></nav><form method="post" class="new-system"><input type="hidden" name="action" value="system"><input name="name" required placeholder="Novo sistema"><button>+ Criar sistema</button></form></aside><main><?php if(!$systemId): ?><section class="empty"><p>Comece criando um sistema.</p></section><?php else: ?><header><div><span class="eyebrow">SISTEMA ATIVO</span><h1><?=htmlspecialchars(array_column($systems,'name','id')[$systemId] ?? '')?></h1></div><a href="#estruturas" class="button">Criar estrutura</a></header><?php if(isset($_GET['created'])): ?><div class="notice"><?=intval($_GET['created'])?> combinações novas geradas.</div><?php endif; ?><section id="visao" class="cards"><article><strong><?=count($types)?></strong><span>Tipos</span></article><article><strong><?=count($elements)?></strong><span>Elementos</span></article><article><strong><?=count($structures)?></strong><span>Estruturas</span></article><article><strong><?=count($combinations)?></strong><span>Combinações</span></article></section><section class="grid"><article class="panel"><h2>Tipos de elemento</h2><form method="post"><input type="hidden" name="action" value="type"><input type="hidden" name="system_id" value="<?=$systemId?>"><input name="name" required placeholder="Ex.: Verbo"><button>Adicionar</button></form><ul><?php foreach($types as $t):?><li><i></i><?=htmlspecialchars($t['name'])?></li><?php endforeach?></ul></article><article class="panel"><h2>Elementos</h2><form method="post"><input type="hidden" name="action" value="element"><input type="hidden" name="system_id" value="<?=$systemId?>"><select name="element_type_id" required><?php foreach($types as $t):?><option value="<?=$t['id']?>"><?=htmlspecialchars($t['name'])?></option><?php endforeach?></select><input name="text_value" required placeholder="Texto do elemento"><button>Salvar</button></form><ul><?php foreach($elements as $e):?><li><small><?=htmlspecialchars($typeNames[$e['element_type_id']] ?? '')?></small><?=htmlspecialchars($e['text_value'])?></li><?php endforeach?></ul></article></section><section id="estruturas" class="panel"><h2>Estruturas ordenadas</h2><p>Adicione tipos na sequência desejada. Cada posição usa somente elementos do tipo escolhido neste sistema.</p><form method="post" class="structure"><input type="hidden" name="action" value="structure"><input type="hidden" name="system_id" value="<?=$systemId?>"><input name="name" required placeholder="Nome da estrutura"><div id="slots"><select name="slots[]" required><?php foreach($types as $t):?><option value="<?=$t['id']?>"><?=htmlspecialchars($t['name'])?></option><?php endforeach?></select></div><button type="button" class="secondary" onclick="addSlot()">+ Posição</button><button>Salvar estrutura</button></form><div class="structures"><?php foreach($structures as $s): $slotLabels=array_map(fn($v)=>$typeNames[$v]??'Tipo removido',json_decode($s['slots'],true)); ?><article><b><?=htmlspecialchars($s['name'])?></b><span><?=htmlspecialchars(implode(' → ',$slotLabels))?></span><form method="post"><input type="hidden" name="action" value="generate"><input type="hidden" name="system_id" value="<?=$systemId?>"><input type="hidden" name="structure_id" value="<?=$s['id']?>"><button>Gerar</button></form></article><?php endforeach?></div></section><section id="resultados" class="panel"><h2>Combinações geradas</h2><div class="results"><?php foreach($combinations as $c):?><code><?=htmlspecialchars($c['value_text'])?></code><?php endforeach?></div></section><?php endif?></main><template id="slot-template"><select name="slots[]" required><?php foreach($types as $t):?><option value="<?=$t['id']?>"><?=htmlspecialchars($t['name'])?></option><?php endforeach?></select></template><script>function addSlot(){document.querySelector('#slots').append(document.querySelector('#slot-template').content.cloneNode(true))}</script></body></html>
